local delay=require("delay")local gpio=require("gpio")local camera=require("camera")local image=require("image")local storage=require("storage")local board_manager=require("board_manager")local led_strip=require("led_strip")local capability=require("capability")local json=require("json")local CONFIG_PATH="/fatfs/config/animal_env.json"local PIN={IR=10,RADAR=12,DHT=9,HEATER=14,FAN=13,MIST=21,LED=38,BUTTON=11}_G.PIN=PIN local CFG={lc=1,cd=30,lm=2000,rpm=120000,rm=30,bdm=50,mpm=3000}local FEISHU="ou_XXXXXXXXXXXXXXXXXXXXXXXX"local g={running=false,strip=nil,disp=nil,sw=0,sh=0,cam=false,cfg=nil,state="IDLE",last_rpt=0,ht=0,fn=0,mt=0,lt=nil,lh=nil,rc=0,mst=0,animal=nil,run_t=os.time(),msg_env=nil}_G.g=g local DB={}local ok,db=pcall(dofile,"/fatfs/config/animal_db.lua")if ok and db then DB=db end local DEF={t_min=15,t_max=30,h_min=40,h_max=70}local BAD={["true"]=1,["false"]=1,["nil"]=1,["null"]=1,["unknown"]=1,["error"]=1,["fail"]=1,["none"]=1,[""]=1,["ok"]=1,["yes"]=1,["no"]=1}local function sd(ms)ms=math.floor(ms+0.5)if ms<=0 then return end while ms>0 do local s=math.min(ms,10)delay.delay_ms(s)ms=ms-s end end local function gg(p)local ok,v=pcall(gpio.get_level,p)if ok then return v end return nil end local function gs(p,v)pcall(gpio.set_level,p,v)end local function gi(p)pcall(gpio.set_direction,p,"input")end local function go(p)pcall(gpio.set_direction,p,"output")end local function initLED() if g.strip then return end local ok,strip=pcall(led_strip.new,PIN.LED,CFG.lc) if ok and strip then g.strip=strip else g.strip=nil end end local function setLED(c)if g.strip then g.strip:set_pixel(0,c.r,c.g,c.b)g.strip:refresh()end end local function rdDHT11(pin)gpio.set_direction(pin,"output")gpio.set_level(pin,0)delay.delay_ms(20)gpio.set_direction(pin,"input")local t=0 while gpio.get_level(pin)==1 do t=t+1 if t>1000 then return nil,"no_resp" end end t=0 while gpio.get_level(pin)==0 do t=t+1 if t>1000 then return nil,"no_high" end end t=0 while gpio.get_level(pin)==1 do t=t+1 if t>1000 then return nil,"no_data" end end local data={}for i=1,40 do t=0 while gpio.get_level(pin)==0 do t=t+1 if t>1000 then return nil,"bit_tout" end end local ht=0 while gpio.get_level(pin)==1 do ht=ht+1 if ht>1000 then return nil,"high_tout" end end data[i]=(ht>8)and 1 or 0 end local hi,hd,ti,td,cs=0,0,0,0,0 for i=1,8 do hi=hi*2+data[i]end for i=9,16 do hd=hd*2+data[i]end for i=17,24 do ti=ti*2+data[i]end for i=25,32 do td=td*2+data[i]end for i=33,40 do cs=cs*2+data[i]end if(hi+hd+ti+td)%256~=cs then return nil,"cs" end return ti+td/10,hi+hd/10 end local function rdDHT()for i=1,3 do local t,h=rdDHT11(PIN.DHT)if t then g.lt,g.lh=t,h return t,h end sd(100)end return g.lt,g.lh end local function txt(m)pcall(capability.call,"feishu_send_message",{message=m},{channel="feishu",chat_id=FEISHU,source_cap="lua_wildlife_monitor"})end local function pic(p,c)pcall(capability.call,"feishu_send_image",{path=p,caption=c or""},{channel="feishu",chat_id=FEISHU,source_cap="lua_wildlife_monitor"})end local function cap(p)local cp=board_manager.get_camera_paths()if not cp then return nil,"no_cam"end pcall(camera.close)sd(300)g.cam=false local ok=pcall(camera.open,cp.dev_path)if not ok then sd(800)local ok2=pcall(camera.open,cp.dev_path)if not ok2 then return nil,"open_fail"end end g.cam=true local fok=pcall(camera.flush)if not fok then pcall(camera.close)g.cam=false return nil,"flush_fail"end for i=1,2 do local gfok,f=pcall(camera.get_frame,3000)if gfok and f then f:release()end end local gfok2,f=pcall(camera.get_frame,3000)if not gfok2 or not f then pcall(camera.close)g.cam=false return nil,"no_frame"end local s=pcall(image.save_file,p,f)f:release()pcall(camera.close)g.cam=false if not s then return nil,"save_fail"end pcall(storage.sync)return p,nil end local function ldCfg()local ok,d=pcall(storage.read_file,CONFIG_PATH)if ok and d then local ok2,c=pcall(json.decode,d)if ok2 and c then g.cfg=c return c end end g.cfg={animal="unknown",temp_threshold={min=15,max=30},humidity_threshold={min=40,max=70}}return g.cfg end local function wrCfg(a,e,s)local c={animal=a,temp_threshold={min=e.t_min,max=e.t_max},humidity_threshold={min=e.h_min,max=e.h_max},source=s or"unknown",timestamp=os.date("%Y-%m-%d %H:%M:%S")}pcall(storage.mkdir,"/fatfs/config")local ok=pcall(storage.write_file,CONFIG_PATH,json.encode(c))if ok then pcall(storage.sync)end return ok,c end local function clean(r)local n=tostring(r or"")local ln=n:lower()if BAD[ln]then return""end n=n:gsub("注.*","")n=n:gsub("：.*","")n=n:gsub(":.*","")n=n:gsub("[\r\n]+"," ")n=n:gsub("%b()"," ")n=n:gsub("%b（）"," ")n=n:gsub("%b【】"," ")n=n:gsub("%b[]"," ")n=n:gsub("[%s%p%c]"," ")n=n:gsub("^[%s%p]+","")n=n:gsub("[%s%p]+$","")n=n:gsub("%s+"," ")if#n>10 then n=n:sub(1,10)end if#n<2 then return""end return n end local function findDB(a)if not a or a==""then return nil end if DB[a]then return DB[a],"exact"end for k,v in pairs(DB)do if a:find(k,1,true)then return v,"sub"end end for k,v in pairs(DB)do if k:find(a,1,true)then return v,"rev"end end return nil,nil end local function iv(t)return t>=-60 and t<=60 end local function ih(h)return h>=0 and h<=100 end local function pt(t)local c={}local p={"温度%s*[:]?%s*(%-?%d+)%s*[°~～至到]%s*(%d+)","适宜%s*温度%s*(%-?%d+)%s*[°~～至到]%s*(%d+)","(%-?%d+)%s*[°Cc]%s*[~～至到]%s*(%d+)%s*[°Cc]","(%-?%d+)%s*度%s*[~～至到]%s*(%d+)%s*度"}for _,pat in ipairs(p)do for a,b in t:gmatch(pat)do local n1,n2=tonumber(a),tonumber(b)if n1 and n2 and iv(n1)and iv(n2)then if n1<n2 then table.insert(c,{min=n1,max=n2})else table.insert(c,{min=n2,max=n1})end end end end if#c==0 then local a,b=t:match("(%-?%d+)%s*[°Cc].-(%d+)%s*[°Cc]")if a and b then local n1,n2=tonumber(a),tonumber(b)if n1 and n2 and iv(n1)and iv(n2)then if n1<n2 then table.insert(c,{min=n1,max=n2})else table.insert(c,{min=n2,max=n1})end end end end if#c>0 then table.sort(c,function(a,b)return(a.max-a.min)<(b.max-b.min)end)return c[1].min,c[1].max end return 15,30 end local function ph(t)local c={}local p={"湿度%s*[:]?%s*(%d+)%s*[%%％]?%s*[~～至到]%s*(%d+)%s*[%%％]?","适宜%s*湿度%s*(%d+)%s*[%%％]?%s*[~～至到]%s*(%d+)%s*[%%％]?","(%d+)%s*[%%％]%s*[~～至到]%s*(%d+)%s*[%%％]?"}for _,pat in ipairs(p)do for a,b in t:gmatch(pat)do local n1,n2=tonumber(a),tonumber(b)if n1 and n2 and ih(n1)and ih(n2)then if n1<n2 then table.insert(c,{min=n1,max=n2})else table.insert(c,{min=n2,max=n1})end end end end if#c==0 then local a,b=t:match("(%d+)%s*[%%％].-(%d+)%s*[%%％]")if a and b then local n1,n2=tonumber(a),tonumber(b)if n1 and n2 and ih(n1)and ih(n2)then if n1<n2 then table.insert(c,{min=n1,max=n2})else table.insert(c,{min=n2,max=n1})end end end end if#c>0 then table.sort(c,function(a,b)return(a.max-a.min)<(b.max-b.min)end)return c[1].min,c[1].max end return 40,70 end local function web(a)local q="野生动物"..a.."适宜生存温度湿度范围 摄氏度"local ok,out,err=capability.call("web_search",{query=q})if not ok or not out then return nil,"fail"end local t1,t2=pcall(function()return pt(out)end)local h1,h2=pcall(function()return ph(out)end)if not t1 or not h1 then return nil,"parse_fail"end return{t_min=t2 or 15,t_max=t2 or 30,h_min=h2 or 40,h_max=h2 or 70},nil end local cv=dofile("/fatfs/scripts/user/cloud_vision.lua")local function insp(p)local r,e=cv.analyze(p)if not r then return nil,e end local n=clean(r)if n==""then return nil,"empty"end return n,nil end local function delPhoto(p)pcall(storage.remove,p)pcall(storage.sync)end local function auto(p)scr("AI识别中...","请稍候")setLED({r=255,g=165,b=0})local a,err=insp(p)if not a then scr("识别失败",tostring(err))setLED({r=255,g=0,b=0})local e=DEF txt("🦊【野生动物监测】\n━━━━━━━━\n⚠️AI识别失败:"..tostring(err).."\n📸照片已保存\n🌡️通常温度:"..e.t_min.."-"..e.t_max.."°C\n💧通常湿度:"..e.h_min.."%-"..e.h_max.."%\n⏰"..os.date("%Y-%m-%d %H:%M:%S"))pic(p,"识别失败")delPhoto(p)sd(5000)scr("Waiting...","Cover sensor")return{success=false,animal="unknown",env=e}end scr("查找配置...",a)local ed,mt=findDB(a)local st,em,e="","",nil if ed then if mt=="exact"then st="【知识库-精确匹配】"em="📚"else st="【知识库-相似匹配】"em="📖"end e={t_min=ed[1],t_max=ed[2],h_min=ed[3],h_max=ed[4]}scr("知识库命中",a.." "..st)else st="【网络搜索】"em="🌐"scr("网络搜索中...",a)local we=web(a)if not we then e=DEF st="【网搜失败-采用通常阈值】"em="⚠️"scr("搜索失败,用默认",a)else e=we end end wrCfg(a,e,st)scr("识别成功!",a.." "..em)setLED({r=0,g=255,b=0})txt("🔮【AI识别结果】\n━━━━━━━━\n"..em.."识别:"..a.."\n"..em.."来源:"..st.."\n🌡️温度:"..e.t_min.."-"..e.t_max.."°C\n💧湿度:"..e.h_min.."%-"..e.h_max.."%\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n━━━━━━━━\n📁配置已写入")pic(p,"AI:"..a.." "..st)delPhoto(p)sd(5000)scr("Waiting...","Cover sensor")return{success=true,animal=a,env=e}end function procResult(a)if not a or a==""then txt("❌识别结果为空")return{success=false}end local ed,mt=findDB(a)local st,em,e="","",nil if ed then if mt=="exact"then st="【知识库-精确匹配】"em="📚"else st="【知识库-相似匹配】"em="📖"end e={t_min=ed[1],t_max=ed[2],h_min=ed[3],h_max=ed[4]}else st="【网络搜索】"em="🌐"local we=web(a)if not we then e=DEF st="【网搜失败-采用通常阈值】"em="⚠️"else e=we end end wrCfg(a,e,st)txt("📋【识别结果】\n━━━━━━━\n"..em.."识别:"..a.."\n"..em.."来源:"..st.."\n🌡️温度:"..e.t_min.."-"..e.t_max.."°C\n💧湿度:"..e.h_min.."%-"..e.h_max.."%\n━━━━━\n💡如需修改请回复:动物"..a)return{success=true,animal=a,env=e}end local function photoS()scr("TRIGGERED!","Capturing...")local id="req_"..tostring(os.time())local R=storage.get_root_dir()local P=storage.join_path(R,"photos")pcall(storage.mkdir,P)local pp=storage.join_path(P,"animal_"..id..".jpg")local r,err=cap(pp)if not r then scr("Capture FAIL",tostring(err))setLED({r=255,g=0,b=0})txt("🔴【监测】\n❌拍照失败:"..tostring(err))return nil end setLED({r=255,g=200,b=0})local res=auto(r)if res and res.success then g.animal=res.animal end return res end local function sH(on)g.ht=on and 1 or 0 gs(PIN.HEATER,on and 1 or 0)end local function sF(on)g.fn=on and 1 or 0 gs(PIN.FAN,on and 1 or 0)end local function sM(on)g.mt=on and 1 or 0 gs(PIN.MIST,on and 1 or 0)end local function stopAll()sH(false)sF(false)sM(false)end local function rpt(animal,env,reason)local t=g.lt or"--"local h=g.lh or"--"txt("🦊【巢穴维护报告】\n━━━━━━━━\n"..(reason or"").."\n✅物种:"..(animal or"unknown").."\n🌡️温度:"..t.."°C 阈值:"..(env.t_min or"?").."-"..(env.t_max or"?").."°C\n💧湿度:"..h.."% 阈值:"..(env.h_min or"?").."%-"..(env.h_max or"?").."%\n🔥加热:"..(g.ht==1 and"开"or"关").." 🌀风扇:"..(g.fn==1 and"开"or"关").." 💨雾化:"..(g.mt==1 and"开"or"关").."\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n━━━━━━━━")end local function btnPressed()local b1=gg(PIN.BUTTON)if not b1 or b1~=0 then return false end sd(CFG.bdm)local b2=gg(PIN.BUTTON)return b2 and b2==0 end local _ai_blogger_mod=nil local function runAIBlogger(animal,env)if not _ai_blogger_mod then local ok,mod=pcall(dofile,"/fatfs/scripts/user/AI_blogger.lua")if ok and type(mod)=="table"then _ai_blogger_mod=mod else txt("❌AI博主:模块加载失败 "..tostring(mod))return end end local sok,serr=pcall(_ai_blogger_mod.run,animal,env)if not sok then txt("【AI博主出错】\n"..tostring(serr))end end local function cleanupBeforeReturn()pcall(camera.close)g.cam=false sd(300)if g.disp then pcall(g.disp.deinit)g.disp=nil sd(300)end gi(PIN.IR)sd(100)if g.strip then pcall(function()g.strip:set_pixel(0,0,0,0)end)pcall(function()g.strip:refresh()end)sd(100)end stopAll()sd(200)end local function nest(env)g.state="MAINTAINING"g.rc=0 g.mst=os.time()local an=(g.animal or"unknown")local first=true local blogFirst=false local blogLast=0 local blogInt=240000 while g.running do local t,h=rdDHT()local rd=gg(PIN.RADAR)if rd and rd~=0 then g.rc=0 else g.rc=g.rc+1 end if g.rc>=CFG.rm then rpt(an,env,"🚪动物已离开")cleanupBeforeReturn()g.running=false txt("🎉 【跳转气象站】") return end if t then if t<env.t_min then sH(true)sF(false)elseif t>env.t_max then sH(false)sF(true)else sH(false)sF(false)end end if h then if h<env.h_min then sM(true)elseif h>env.h_max then sM(false)end end if first then rpt(an,env,"🟢巢穴维护已启动")first=false end if rd and rd~=0 then scr("MAINTAIN","T:"..tostring(t or"--").." H:"..tostring(h or"--").." RD:1")else scr("MAINTAIN","T:"..tostring(t or"--").." H:"..tostring(h or"--").." RD:("..g.rc..")")end local now=os.time()*1000 if now-g.last_rpt>=CFG.rpm then g.last_rpt=now rpt(an,env,"📊定期上报")end if btnPressed() then txt("🛠️【调试】\n \n🔘按键触发\n维护中断\n等待红外触发\n⏰"..os.date("%Y-%m-%d %H:%M:%S"))break end if not blogFirst then blogFirst=true blogLast=now runAIBlogger(an,env) else if now - blogLast >= blogInt then blogLast=now runAIBlogger(an,env) end end sd(CFG.lm)end cleanupBeforeReturn()g.state="IDLE"g.animal=nil end local function parseMsg(msg)if not msg or msg==""then return nil end local m=msg:lower()local env={t_min=nil,t_max=nil,h_min=nil,h_max=nil}local hasT,hasH=false,false local t1,t2=m:match("温度阈值[%s]*(%-?%d+)[%s]*[~～%-至到]%s*(%d+)")if not t1 then t1,t2=m:match("温度阈值[%s]*(%-?%d+)[%s]+(%d+)")end if t1 and t2 then local n1,n2=tonumber(t1),tonumber(t2)if n1 and n2 and n1>=-60 and n1<=60 and n2>=-60 and n2<=60 then if n1<n2 then env.t_min,env.t_max=n1,n2 else env.t_min,env.t_max=n2,n1 end hasT=true end end local h1,h2=m:match("湿度阈值[%s]*(%d+)[%s]*[~～%-至到]%s*(%d+)")if not h1 then h1,h2=m:match("湿度阈值[%s]*(%d+)[%s]+(%d+)")end if h1 and h2 then local n1,n2=tonumber(h1),tonumber(h2)if n1 and n2 and n1>=0 and n1<=100 and n2>=0 and n2<=100 then if n1<n2 then env.h_min,env.h_max=n1,n2 else env.h_min,env.h_max=n2,n1 end hasH=true end end if hasT or hasH then if not env.t_min then env.t_min,env.t_max=DEF.t_min,DEF.t_max end if not env.h_min then env.h_min,env.h_max=DEF.h_min,DEF.h_max end return env end return nil end local function checkMsg()local ok,msgs=pcall(capability.call,"feishu_get_messages",{limit=5},{channel="feishu",chat_id=FEISHU,source_cap="lua_wildlife_monitor"})if not ok or not msgs or type(msgs)~="table"then return nil end for _,m in ipairs(msgs)do if m and m.text and m.text~=""then local env=parseMsg(m.text)if env then return env,m.text end end end return nil end local function syncDevState()local vh=gg(PIN.HEATER)local vf=gg(PIN.FAN)local vm=gg(PIN.MIST)g.ht=(vh==1)and 1 or 0 g.fn=(vf==1)and 1 or 0 g.mt=(vm==1)and 1 or 0 end function run()dofile("/fatfs/scripts/user/display.lua")ldCfg()gi(PIN.IR)gi(PIN.RADAR)gi(PIN.DHT)go(PIN.HEATER)go(PIN.FAN)go(PIN.MIST)gi(PIN.BUTTON)initLED()initDisp()g.running=true g.state="IDLE"g.animal=nil g.run_t=os.time()scr("Waiting...","Cover sensor")local msg_t=0 local disp_t=0 while g.running do rdDHT()syncDevState()local now=os.time()*1000 if now-disp_t>=500 then disp_t=now if g.state=="IDLE"then scr("Waiting...","T:"..tostring(g.lt or"--").." H:"..tostring(g.lh or"--"))end end if g.state=="IDLE"then gi(PIN.IR)  local ir=gg(PIN.IR)if ir==0 then local r=photoS()if r and r.success then if r.animal and(r.animal:lower():find("蛋")or r.animal:lower():find("egg")or r.animal:lower():find("卵")or r.animal:lower():find("bird egg"))then txt("🎯【检测到鸟蛋】\n \n识别:"..r.animal.."\n🥚进入孵蛋模式\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n ")cleanupBeforeReturn() dofile("/fatfs/scripts/user/incubator.lua")return else local env=r.env local rd=gg(PIN.RADAR)if rd and rd~=0 then nest(env)else txt("🔴【监测】\n雷达未检测到动物，跳过维护\n")end end end sd(CFG.cd*1000)end local now2=os.time()*1000 if now2-msg_t>=CFG.mpm then msg_t=now2 local env,raw=checkMsg()if env then g.msg_env=env txt("📚输入\n  \n收到:"..(raw or"").."\n🌡️温度:"..env.t_min.."-"..env.t_max.."°C\n💧湿度:"..env.h_min.."%-"..env.h_max.."%\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n  \n🟢进入巢穴维护")g.animal="飞书控制"nest(env)end end elseif g.state=="MAINTAINING"then sd(1000)end sd(100)end cleanupBeforeReturn()end function stop()g.running=false end if args and args.action=="process_result"then procResult(args.animal_name)else run()end